INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (234, 'Ahh, excellent. It''s been a while since I received word from Ironforge. Ach, these letters from me mum warm my heart. Here, not fair you don''t get some readin'', too. Take one of these manuals we have lyin'' around.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Coldridge Valley Mail Delivery
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (353, 'Aha!  So Grimand finally finished my axe!  I can''t wait to try it against some troggs and kobolds!$B$BMany thanks, $n.  It was a long distance to travel for this delivery.   Here are some coins for your efforts.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Stormpike's Delivery
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (92727, '<The satchel lying before you has a few specks of what appears to be dried blood on the flap. Studying the stain, you notice that the flap also has a name embroidered onto it. It reads "Fillion Flamebreeze".>', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- The Missing Scholar
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (94373, 'Well done, $Glad:lass;. Ye''ve proven yerself ready. Earth''s the bedrock of all things. It''ll shield ye, but only if ye show it proper respect. Even stone can shift if slighted. Learn its ways, and ye''ll grow wiser than most. Never forget the secrets it shares. $B$BI''ll craft ye a sapta now--accept it, and ye''ll walk the true path.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Call of Earth
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (94374, 'Ah... $n... the earth welcomes you, even in this frozen land. Bound in body and spirit, you''ll walk forward knowing the mountains are your strength, the plains your patience, and the world your essence.$B$BTo pass this rite, stand humbly before the earth. The other elements are not so still--they clash and roar. Learn their dual nature, even here among the snow and stone.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Call of Earth
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (94375, 'Well done! Know this--totems ain''t just a mark of yer place among shamans. They''re tools, a focus for spells tied to stone, soil, and other elements. As ye grow wiser, more o'' the mountain''s power will open to ye. The trainers will know when yer ready for more. But for now, take this totem, and let the ground speak through ye.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Call of Earth
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (94449, 'Hmm... that elder sent ye, eh? Well, a shaman''s word is solid, so I''ll not argue. That means ye''re ready for the next sapta. The sapta of fire. I see it in yer eyes already -- the burnin'', the hunger. Ye''ve tasted power, and now ye want more. But mind yerself, $n. Remember what the stone taught ye. Fire''s easy to wield, but harder to master. Know when to hold back.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Call of Fire
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (94912, 'Greetings, fellow $c. It pleases me to meet a fellow druid from among the Skyborne, and to be among the first to welcome you to Azeroth.$B$BI think you will find that my fellow druids of the Cenarion Circle have much wisdom to impart upon you, child of nature.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Child of Nature
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (94914, 'Ah I see that you have already mastered the form of the Bear. Good, good. You are well on your way, young druid.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Moonglade
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (95213, '<The dwarf turns pale as he sees the empty keg.>$B$B...Where did you find this?', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Stolen Blasting Powder
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (96044, 'There you have it, you can now craft your very own Sharpening Wheel. Most folk don''t care much for camps being set up in the center of town, so you''ll need to head into the wilderness if you want to test it out.$B$BOh, and just remember, no camp is complete without a campfire. You''ll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven''t already, you might want to check in with someone who can train you in the culinary arts to learn the basics.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Camping 101: Blacksmithing
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (96046, 'There you have it, you can now craft your very own Lodestone. Most folk don''t care much for camps being set up in the center of town, so you''ll need to head into the wilderness if you want to test it out.$B$BOh, and just remember, no camp is complete without a campfire. You''ll need one of those before you start up your camp. Most cooks can teach you to make a fire. If you haven''t already, you might want to check in with someone who can train you in the culinary arts to learn the basics.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Camping 101: Mining
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (96392, 'So ye see now, $c? Thick as cockroaches they are, and that''s just the ones we can see from the sky.$B$BYe look like a sturdy enough sort. How''s about a bit o'' violence?', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Farsen's Watch
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (96408, 'Greetings, friend. How are ya?', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- A Visitor to Dun Morogh
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (96608, 'So now that we''ve learned the basics, why don''t you go and learn a tradeskill from the trainers in the village nearby. They will also teach you how to create a camp fixture suitable to your new profession.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- The Great Outdoors
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (96628, 'You say these are from the mountaineers? Aye, I could use them. Thank you, $c.$B$BHey, you''ve got the look of an adventurer yourself. How would you like to learn about camping?', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- The Adventurer
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (98319, 'Ach, the fool...$B$BThank ye for the help, $n. Guess we have our report.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Secure the Mountain
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (98321, 'Now that''s more like it! With these shipments we''ll get the forge back up and runnin'' in no time!', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Flintfire's Shipment
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (98323, 'Completely overrun? Why am I not surprised.$B$BWell, that''s going in the report too.$B$B<Senir folds Gretchen''s letter into his pile of notes>', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Secure the Mountain
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (99158, 'Ah. Candles from Ironforge. $B$BWhile I am mostly able to live independently in my hermitage, there are a few key things that I appreciate from the city and the pious.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Dawn in the Mountains
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (99159, 'Ah, perfect. These will do--any that are too wet to use right now I will leave to dry.$B$BNow, if you''re willing, I have more tasks I could use help with.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Finding Warmth
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (99160, 'I wish we could have simply placated them. Unfortunately it was beyond my knowledge and they were too dangerous to leave unchecked.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Rime's Wrath
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (99161, 'Light bless you, $c. Your efforts make this area much safer and hopefully will prevent unnecessary deaths.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Rime's Wrath
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) VALUES (99162, 'The mountaineers engrave their names on the stock of their rifles. It helps identify them should something happen. I''ll send these back to Ironforge--there someone will pass them on to any family.', 70888) ON DUPLICATE KEY UPDATE `RewardText` = VALUES(`RewardText`), `VerifiedBuild` = 70888; -- Treacherous Cold
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (353, 'You come all the way from Stormwind?  I hear it''s getting dicey down there in the human lands, with brigands and orcs running about.  A perfect place for a $c to prove their worth!', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Stormpike's Delivery
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (92596, 'Our land is going through changes, but there may yet be some good to come of this.', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- The High Order
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (92597, 'Realizing our true potential as sons and daughters of the highborne is our only path to salvation. The Windshapers are little better than the Al''Aketh, supplicating themselves to uncaring, otherworldly creatures.', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Reading the Leylines
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (93461, 'This place isn''t much, but it''s home.', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Welcome to Shen'dar Village
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (94373, 'Patience, $Glad:lass;, is the earth''s finest virtue. It''s seen mountains crumble and rivers carve valleys--slow and stubborn, like a true dwarf. The earth calls to ye now, for trouble brews on the horizon. Return successful, and ye''ll be one step closer to bein'' whole.$B$BOthers may envy yer wisdom, but that''s their burden to bear.', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Call of Earth
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (94375, 'Ahh, ye''ve returned. If ye have the stone, it means the mountain''s chosen ye true. I''ll give ye the totem it promised. But if ye''ve come empty-handed, off with ye! The path ain''t for those who forget their way.', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Call of Earth
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (94414, 'My gift is simple, and mundane. I cannot peer between worlds such as those with the skysight, nor can I draw upon the magic of the leylines beneath Zephras like others can. But a gift it remains and I am grateful to have it.$B$BAppreciation of what you have is the key to happiness. Yearning for what you may have, or what you have lost, only leads to despair.', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- The Anchors of Zephras
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (95213, 'What''s that you''ve got?', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Stolen Blasting Powder
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (96044, 'Yes, I can teach you.', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Camping 101: Blacksmithing
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (96390, 'How''d it go? Did ye give ''em what-for?', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Nip 'Em in the Bud
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (96628, 'Are you here to learn about camping in the wilderness?', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- The Adventurer
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (96629, 'A good campfire is the foundation to any good camp.', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Camping 101: Cooking
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (96646, 'A good campfire is the foundation to any good camp.', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Camping 101: Cooking
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (98321, 'Wendigos are nasty beasties. It''s just good all the miners made it out of the Grizzled Den in one piece!', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Flintfire's Shipment
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (98323, 'Ah, you''re back just in time.$B$BWhat''s the matter, $Glad:lass;? You look like you''ve seen a ghost.', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Secure the Mountain
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (99158, 'Why did the Light guide you here today?', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Dawn in the Mountains
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (99159, 'Light guide you on your tasks.', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Finding Warmth
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (99161, '''Ware the winter, friend.', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Rime's Wrath
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) VALUES (99162, 'What do you need?', 70888) ON DUPLICATE KEY UPDATE `CompletionText` = VALUES(`CompletionText`), `VerifiedBuild` = 70888; -- Treacherous Cold
